package com.wissfind.marketplace.service; import io.jsonwebtoken.Claims; import org.springframework.security.core.context.SecurityContextHolder; public class CurrentUser { public static Long id(){Object d=SecurityContextHolder.getContext().getAuthentication().getDetails(); if(d instanceof Claims c)return Long.valueOf(String.valueOf(c.get("id"))); throw new IllegalStateException("Unauthenticated");} public static String role(){return SecurityContextHolder.getContext().getAuthentication().getAuthorities().iterator().next().getAuthority().replace("ROLE_","");}}
